/* @prim:begin 39-theme-toggle */
:root{color-scheme:dark;}
@media (prefers-color-scheme: light){:root:not([data-theme="dark"]){--bg:#f7f8fa;--surface:#ffffff;--surface-2:#eef1f5;--elevated:#eef1f5;--border:#d5dbe3;--text:#1c2430;--text-secondary:#475262;--muted:#566170;--dimmed:#475262;--cyan:#00606b;--cyan-bg:rgba(0,96,107,0.09);--green:#047857;--green-bg:rgba(4,120,87,0.09);--gold:#6b5400;--gold-bg:#fff3c4;--red:#b42344;--red-bg:rgba(180,35,68,0.08);color-scheme:light;}}
:root[data-theme="light"]{--bg:#f7f8fa;--surface:#ffffff;--surface-2:#eef1f5;--elevated:#eef1f5;--border:#d5dbe3;--text:#1c2430;--text-secondary:#475262;--muted:#566170;--dimmed:#475262;--cyan:#00606b;--cyan-bg:rgba(0,96,107,0.09);--green:#047857;--green-bg:rgba(4,120,87,0.09);--gold:#6b5400;--gold-bg:#fff3c4;--red:#b42344;--red-bg:rgba(180,35,68,0.08);color-scheme:light;}
.themebtn{display:inline-flex;align-items:center;min-height:44px;padding:0;margin:0 0 8px;font:inherit;font-size:var(--fs-body);color:var(--text-secondary);background:none;border:0;cursor:pointer;text-underline-offset:3px;}
.themebtn:hover,.themebtn:focus-visible{color:var(--cyan);text-decoration:underline;}
.themebtn:focus-visible{outline:2px solid var(--cyan);outline-offset:2px;}
@media print{:root{--bg:#f7f8fa;--surface:#ffffff;--surface-2:#eef1f5;--elevated:#eef1f5;--border:#d5dbe3;--text:#1c2430;--text-secondary:#475262;--muted:#566170;--dimmed:#475262;--cyan:#00606b;--cyan-bg:rgba(0,96,107,0.09);--green:#047857;--green-bg:rgba(4,120,87,0.09);--gold:#6b5400;--gold-bg:#fff3c4;--red:#b42344;--red-bg:rgba(180,35,68,0.08);color-scheme:light;} .themebtn{display:none!important;} body{background:#fff!important;}}
/* @prim:end 39-theme-toggle */
/* @prim:begin 45-fact-tile */
.ftiles-c{container-type:inline-size;min-width:0}
.ftiles{display:grid;grid-template-columns:minmax(0,1fr);gap:14px 8px;margin:0;padding:0;list-style:none}
@container (min-width:28rem){.ftiles{grid-template-columns:repeat(2,minmax(0,1fr))}}
@container (min-width:54rem){.ftiles.is-4{grid-template-columns:repeat(4,minmax(0,1fr))}}
.ftiles.is-fit{grid-template-columns:repeat(auto-fit,minmax(min(100%,13.75rem),1fr))}
.ftile{position:relative;display:grid;grid-row:span 3;grid-template-rows:subgrid;row-gap:0;min-width:0;isolation:isolate}
.ftile::before{content:"";grid-row:2/4;grid-column:1;border:1px solid var(--border);border-radius:var(--ds-r-sm);background:var(--surface);z-index:-1}
.ftile-lab{grid-row:1;grid-column:1;padding:0 2px 4px;font-size:.75rem;font-weight:700;line-height:1.2;letter-spacing:.06em;text-transform:uppercase;color:var(--cyan)}
.ftile-fig{grid-row:2;grid-column:1;padding:12px 14px 0;font-size:var(--fs-headline);font-weight:700;line-height:1.25;font-variant-numeric:tabular-nums;color:var(--text)}
.ftile-cap{grid-row:3;grid-column:1;padding:6px 14px 12px;color:var(--text-secondary);font-size:.9rem;line-height:1.45;text-wrap:pretty}
/* @prim:end 45-fact-tile */
/* @prim:begin 48-summary-disclosure */
.sumd{border:1px solid var(--border);border-radius:var(--ds-r-sm);background:var(--surface);padding:0 14px}
.sumd>summary{display:flex;flex-wrap:wrap;align-items:center;gap:2px 10px;min-height:52px;padding:8px 0;cursor:pointer;list-style:none}
.sumd>summary::-webkit-details-marker{display:none}
.sumd>summary:focus-visible{outline:2px solid var(--cyan);outline-offset:2px;border-radius:var(--ds-r-xs)}
.sumd-chev{width:1rem;height:1rem;flex:none;color:var(--cyan);transition:transform var(--dur-base) var(--ease-out)}
.sumd[open] .sumd-chev{transform:rotate(90deg)}
.sumd-t{font-weight:600;font-size:var(--fs-headline)}
.sumd-s{color:var(--text-secondary)}
.sumd[open]>summary{border-bottom:1px solid var(--border);margin-bottom:14px}
.sumd .ftiles{margin:0 0 12px}
.sumd-note{margin:0 0 14px;padding:10px 14px;border-radius:var(--ds-r-sm);background:var(--surface-2);color:var(--text-secondary);font-size:.9rem;line-height:1.5}
@media (prefers-reduced-motion:reduce){.sumd-chev{transition:none}}
/* @prim:end 48-summary-disclosure */

