function kIcon(k){return '<svg viewBox="0 0 16 16" aria-hidden="true" focusable="false" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round">'+KI[k]+'</svg>';}
function kEsc(s){return String(s).replace(/[&<>"]/g,function(c){return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c];});}
function kSlot(i){return i===undefined?document.querySelector('[data-stage]'):document.querySelector('[data-state="'+i+'"]');}
var SD={title:'The whole plan',summary:'Five working days to a scoped MVP plan, for a fixed $4,800.',tiles:[['Price','$4,800','Fixed, invoiced at signing'],['Length','5 working days','After the start items are in'],['You get','A scoped MVP plan','Written for your counsel and team'],['Then','Your call on Step 2','No obligation to continue']],note:'Prices hold for 30 days from the date on the agreement.'};
function kitSummaryDisclosure(host,d,open){var x=document.createElement('details');x.className='sumd';if(open)x.open=true;x.innerHTML='<summary><svg class="sumd-chev" viewBox="0 0 16 16" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round">'+KI.right+'</svg><span class="sumd-t">'+kEsc(d.title)+'</span><span class="sumd-s">'+kEsc(d.summary)+'</span></summary><ul class="ftiles is-fit" aria-label="'+kEsc(d.title)+'">'+d.tiles.map(function(r){return '<li class="ftile"><span class="ftile-lab">'+kEsc(r[0])+'</span><b class="ftile-fig">'+kEsc(r[1])+'</b><span class="ftile-cap">'+kEsc(r[2])+'</span></li>';}).join('')+'</ul>'+(d.note?'<p class="sumd-note">'+kEsc(d.note)+'</p>':'');host.appendChild(x);return x;}
kitSummaryDisclosure(kSlot(),SD,false);
